		tgt.[bankinformationorigin] = src.[bankinformationorigin],
		tgt.[workflowstate] = src.[workflowstate],
		tgt.[versioningstate] = src.[versioningstate],
		tgt.[sks_eft_acctstatus] = src.[sks_eft_acctstatus],
		tgt.[sks_eft_prenotestatus] = src.[sks_eft_prenotestatus],
		tgt.[workflowtype] = src.[workflowtype],
		tgt.[sysdatastatecode] = src.[sysdatastatecode],
		tgt.[accountid] = src.[accountid],
		tgt.[accountnum] = src.[accountnum],
		tgt.[activedate] = src.[activedate],
		tgt.[bankaccountnamekana_jp] = src.[bankaccountnamekana_jp],
		tgt.[bankcin] = src.[bankcin],
		tgt.[bankconstantsymbol] = src.[bankconstantsymbol],
		tgt.[bankcontractaccount] = src.[bankcontractaccount],
		tgt.[bankgroupid] = src.[bankgroupid],
		tgt.[bankiban] = src.[bankiban],
