		tgt.[exchrate] = src.[exchrate],
		tgt.[exchrateref] = src.[exchrateref],
		tgt.[expirydate] = src.[expirydate],
		tgt.[foreignaccount_ru] = src.[foreignaccount_ru],
		tgt.[foreignbank_ru] = src.[foreignbank_ru],
		tgt.[foreignswift_ru] = src.[foreignswift_ru],
		tgt.[intermaccount_ee] = src.[intermaccount_ee],
		tgt.[intermbank_ee] = src.[intermbank_ee],
