		tgt.[sms] = src.[sms],
		tgt.[specificsymbol] = src.[specificsymbol],
		tgt.[swiftno] = src.[swiftno],
		tgt.[telefax] = src.[telefax],
		tgt.[telex] = src.[telex],
		tgt.[url] = src.[url],
		tgt.[vendaccount] = src.[vendaccount],
		tgt.[vendduns4number] = src.[vendduns4number],
		tgt.[vendpaymenttextcode] = src.[vendpaymenttextcode],
		tgt.[ficreditorid_dk] = src.[ficreditorid_dk],
